    int sampleCount = 1;
    void record() { sampleCount++; }
}
class SensorPod {
    SensorCore core = new SensorCore();
    void collect() { core.record(); }
}
class WeatherStation {
    SensorPod pod = new SensorPod();
    void logData() { pod.collect(); }
}
public class Main {
    public static void main(String[] args) {
        WeatherStation station = new WeatherStation();
        station.logData();
        station.logData();
        System.out.println(station.pod.core.sampleCount);
    }
}
```
